using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class AwariPrefabInstall {
 const string Path="Assets/Shioka/調整Data/Fighter/Awari/Awari.prefab";
 public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");var actors=UnityEngine.Object.FindObjectsByType<TrainingFighter>(FindObjectsSortMode.None);if(actors.Length!=2||AssetDatabase.LoadMainAssetAtPath(Path)!=null)throw new Exception("Expected two plain actors and no existing prefab");var original=actors.First(a=>a.GetComponent<ApprovedLocomotionTuning>()!=null);var template=UnityEngine.Object.Instantiate(original.gameObject);template.name="Awari";template.transform.position=Vector3.zero;try{foreach(var c in template.GetComponents<MonoBehaviour>())if(!(c is TrainingFighter)&&!(c is TrainingMotor2D)&&!(c is ArmoredStaticPoseView))UnityEngine.Object.DestroyImmediate(c);var fighter=template.GetComponent<TrainingFighter>();fighter.opponent=null;fighter.inputSourceBehaviour=null;fighter.presentation=template.GetComponent<ArmoredStaticPoseView>();var combat=original.GetComponent<CombatTestV01>();fighter.moveSet=combat.profile.moves;fighter.hurtboxProfile=combat.profile.hurtboxes;PrefabUtility.SaveAsPrefabAsset(template,Path);}finally{UnityEngine.Object.DestroyImmediate(template);}var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Path);if(prefab.GetComponent<ApprovedLocomotionTuning>()!=null||prefab.GetComponent<CombatTestV01>()!=null||prefab.GetComponent<TrainingControls>()!=null)throw new Exception("Role code leaked into fighter prefab");foreach(var actor in actors){string name=actor.name;var before=actor.GetComponents<MonoBehaviour>().Where(c=>c!=null).ToDictionary(c=>c.GetType(),c=>JsonUtility.ToJson(c));var size=actor.GetComponent<TrainingMotor2D>().Shape.size;var settings=new ConvertToPrefabInstanceSettings{objectMatchMode=ObjectMatchMode.ByHierarchy,componentsNotMatchedBecomesOverride=true,gameObjectsNotMatchedBecomesOverride=true,recordPropertyOverridesOfMatches=true};PrefabUtility.ConvertToPrefabInstance(actor.gameObject,prefab,settings,InteractionMode.AutomatedAction);actor.name=name;if(!PrefabUtility.IsPartOfPrefabInstance(actor)||actor.GetComponent<TrainingMotor2D>().Shape.size!=size)throw new Exception("Body/prefab changed");foreach(var item in before){var component=actor.GetComponent(item.Key);if(component==null||JsonUtility.ToJson(component)!=item.Value)throw new Exception("Scene field changed: "+name+" "+item.Key);}if(actor.opponent==null||actor.presentation==null)throw new Exception("Scene references lost");}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Debug.Log("AWARI_PREFAB both actors linked; original component fields/body/role overrides unchanged; extra player tuning preserved only where it existed");}
}
